function parseManagedReviewFinalProposal(result: HostRunResult): ManagedReviewFinalProposalInput {
  if (result.finalAssistantResultTruncated) {
    throw new Error('managed_review_final_result_oversize');
  }
  if (result.finalAssistantResultCount > 1) {
    throw new Error('managed_review_final_result_multiple');
  }
  if (result.finalAssistantResultCount !== 1 || result.finalAssistantResult === null) {
    throw new Error('managed_review_final_result_missing');
  }
  const classification = classifyManagedReviewFinalEnvelope(result.finalAssistantResult);
  if (classification.kind !== 'valid') throw new Error('managed_review_final_result_malformed');
  const envelope = classification.envelope;
  const conclusion = envelope.conclusion;
  return {
    storyId: envelope.storyId,
    providerAgent: envelope.providerAgent,
    lane: envelope.lane,
    reviewRunId: envelope.reviewRunId,
    conclusion,
    ...(conclusion === 'pass' ? { note: envelope.note as string | undefined } : {
      findings: envelope.findings as ManagedReviewEvidenceFindingProposal[] | undefined,
    }),
    readManifest: envelope.readManifest as ReviewerReadManifest,
    ...(envelope.readLog !== undefined ? { readLog: envelope.readLog as ReviewerReadLogEvidence } : {}),
    ...(envelope.readDiagnostics !== undefined ? { readDiagnostics: envelope.readDiagnostics as ReviewerReadDiagnostic[] } : {}),
  };
}

export function writeManagedReviewEvidenceProposal(args: {
      storyId?: string;
      providerAgent?: string;
      lane?: string;
      reviewRunId?: string;
      conclusion?: 'pass' | 'findings';
      note?: string;
      findings?: ManagedReviewEvidenceFindingProposal[];
      readManifest?: unknown;
      readLog?: unknown;
      readDiagnostics?: unknown;
    }) {
      assertOnlyKeys('managed_review_proposal_set', args as Record<string, unknown>, [
        'runId', 'storyId', 'providerAgent', 'lane', 'reviewRunId', 'conclusion',
        'note', 'findings', 'readManifest', 'readLog', 'readDiagnostics',
      ]);
      if (!args.storyId || !args.providerAgent || !args.lane || !args.reviewRunId || !args.conclusion || args.readManifest === undefined) {
        throw new Error('managed_review_proposal_set: storyId/providerAgent/lane/reviewRunId/conclusion/readManifest are required');
      }
      let runId = args.runId?.trim() || process.env.LATTICE_MANAGED_HOST_RUN_ID?.trim() || '';
      let providerInvocationPid: number | undefined;
      const providerInvocationAttestation = readManagedReviewProposalInvocationFromFd();
      if (!runId) {
        if (providerInvocationAttestation) {
          runId = providerInvocationAttestation.runId;
        } else {
          runId = resolveManagedReviewProposalInvocation({
            root: ctx.root,
            binding: {
              storyId: args.storyId,
              providerAgent: args.providerAgent,
              lane: args.lane,
              reviewRunId: args.reviewRunId,
            },
          });
          providerInvocationPid = process.pid;
        }
      }
      const proposal = writeManagedReviewEvidenceProposal({
        root: ctx.root,
        runId,
        environment: process.env,
        ...(providerInvocationPid !== undefined ? { providerInvocationPid } : {}),
        ...(providerInvocationAttestation ? { providerInvocationAttestation } : {}),
        proposal: {
          storyId: args.storyId,
          providerAgent: args.providerAgent,
          lane: args.lane,
          reviewRunId: args.reviewRunId,
          conclusion: args.conclusion,
          ...(args.note !== undefined ? { note: args.note } : {}),
          ...(args.findings !== undefined ? { findings: args.findings } : {}),
          readManifest: args.readManifest as never,
          ...(args.readLog !== undefined ? { readLog: args.readLog as never } : {}),
          ...(args.readDiagnostics !== undefined ? { readDiagnostics: args.readDiagnostics as never } : {}),
        },
      });
      return {
        schemaVersion: proposal.schemaVersion,
        runId,
        conclusion: proposal.conclusion,
        authoredAt: proposal.authoredAt,
      };
    },

    managed_review_evidence_import(args: { runId?: string; receiptId?: string }) {
      assertOnlyKeys('managed_review_evidence_import', args as Record<string, unknown>, ['runId', 'receiptId']);
      const runId = args.runId?.trim() || '';
      const receiptId = args.receiptId?.trim() || '';
      if (!runId || !receiptId) throw new Error('managed_review_evidence_import: runId and receiptId are required; verdict overrides are not accepted');
      const managedRun = readManagedHostRunBinding(ctx.root, runId);
      if (!managedRun.storyId || !managedRun.reviewRunId || !managedRun.lane || managedRun.profile !== 'managed_reviewer') {
        throw new Error('managed_review_evidence_import: run is not an exact managed_reviewer binding');
      }
      assertCwdInWorktree(ctx.store, managedRun.storyId);
      const story = ctx.store.readStory(managedRun.storyId);
      const reviewRun = assertCurrentReviewRunForEvidence(
        ctx.store,
        story,
        ctx.root,
        managedRun.lane,
        managedRun.reviewRunId,
      );
      // ReviewRun's advisory freshness policy is deliberately permissive for
      // some consumers, but receipt import is an authority-creating write. It
      // must bind to the LIVE tree, not merely an old otherwise-valid review
      // tuple: once either head or material changed, re-dispatch/re-review is
      // required before a managed provider verdict can become gate evidence.
      const gitCwd = resolveGitCwd({
        store: ctx.store,
        storyId: managedRun.storyId,
        metadataRoot: ctx.root,
        projectRoot: ctx.root,
      });
      // This check deliberately remains a closure rather than a one-time
      // preflight. Receipt verification and lock acquisition can take long
      // enough for a concurrent commit to change the reviewed tree. Recheck
      // while both canonical persistence locks are held immediately before
      // admitting an existing receipt or writing any new evidence/binding.
      const assertLiveReviewMaterial = (): void => {
        const liveHeadHash = currentGitHead(gitCwd);
        const liveMaterialHash = currentMaterialHash(gitCwd, 'HEAD', ctx.root);
        if (!liveHeadHash || !liveMaterialHash || liveMaterialHash !== reviewRun.materialHash) {
          throw new Error(
            `managed_review_evidence_import: live review material drift (head=${reviewRun.headHash}/${liveHeadHash ?? 'unavailable'}, `
            + `material=${reviewRun.materialHash}/${liveMaterialHash ?? 'unavailable'}); rerun the managed reviewer`,
          );
        }
        // A first receipt can auto-commit only story metadata before another
        // required lane imports its completed receipt. That deliberately moves
        // HEAD, but currentMaterialHash excludes that metadata and remains the
        // authoritative source/material closure. The receipt is still bound to
        // the signed original head by `expected` below, while the current-round
        // and lane checks above keep this exception scoped to the same review.
      };
      const expected = {
        providerHost: managedRun.host,
        headHash: reviewRun.headHash,
        materialHash: reviewRun.materialHash,
        storyFilesHash: reviewRun.storyFilesHash ?? reviewRun.workspaceBinding?.storyFilesHash ?? '',
        promptHash: reviewRun.promptHash,
        envelopeId: reviewRun.envelopeId ?? null,
        managedPromptDigest: managedReviewerPromptDigest(reviewRun.workspaceBinding?.metadataRoot ?? ctx.root, reviewRun),
      };
      const sealedProposal = readManagedReviewEvidenceProposal(ctx.root, runId);
      const intake = createManagedReviewEvidenceBinding({
        root: ctx.root,
        storyId: managedRun.storyId,
        providerAgent: managedRun.agentType,
        lane: managedRun.lane,
        reviewRunId: managedRun.reviewRunId,
        runId,
        'candidate-binding managed reviewer did not reach terminal');
      const status = await getManagedHostRunStatus({ root: candidateRoot, runId: submitted.run.runId });
      assert.equal(status.run.terminal?.state, 'completed',
        `candidate-binding managed reviewer must complete: ${status.run.terminal?.reason}`);
      return { runId: submitted.run.runId, receiptId: managedHostRunReceipt(candidateRoot, submitted.run.runId).receiptId };
    };
    const envelope = (conclusion: 'pass' | 'findings', readManifest: ReturnType<typeof manifest>) => ({
      schemaVersion: 'lattice.managed_review_final_proposal.v1',
      storyId: STORY_ID,
      providerAgent: LANE,
      lane: LANE,
      reviewRunId: REVIEW_RUN_ID,
      conclusion,
      ...(conclusion === 'pass'
        ? { note: 'The provider completed the candidate-bound managed review.' }
        : { findings: [{
          desc: 'The provider found a candidate-bound managed review defect.',
          severity: 'medium',
          category: 'missing',
        }] }),
      readManifest,
    });
    const handlers = createManagedReviewEvidenceHandlers({
      store,
      root: candidateRoot,
      scanRoot: join(candidateRoot, 'packages/main'),
    });

    const rejectedPass = await completeReceipt(envelope('pass', manifest([])));
    assert.throws(
      () => handlers.managed_review_evidence_import(rejectedPass),
      /candidate routing evidence rejected: read manifest is missing candidate full reads/,
      'a managed pass with matching routing digests but no full candidate read is rejected',
    );
    assert.equal(store.readReviewPasses(STORY_ID).passes.length, 0,
      'rejected candidate-incomplete managed pass creates no REVIEW evidence');

