function synthesizedBlocked(materialHash: string, reason: string, summary: string): CodexReviewVerdict {
  return {
    schemaVersion: CODEX_REVIEW_VERDICT_SCHEMA,
    decision: 'blocked',
    materialHash,
    findings: [],
    summary,
    reason,
  };
